import{_ as l,o as s,c as n,a4 as i}from"./chunks/framework.B-wJupoK.js";const e="/assets/image-20260311231752219.MNlNbEPl.png",t="/assets/image-20260311233226605.D_TMzFVI.png",p="/assets/image-20260311233258430.CQb8g2nC.png",r="/assets/image-20260311233441258.CcWwn6yP.png",o="/assets/image-20260311234237483.BASpPrpA.png",c="/assets/image-20260311234304859.DGki6-CF.png",h="/assets/image-20260312083431580.Ba8HtKW6.png",k="/assets/image-20260312083530044.KuQ9w_97.png",d="/assets/image-20260312084804933.BiPc7pOG.png",g="/assets/image-20260312090150742.B-goY4xW.png",b="/assets/image-20260312090455124.DEYTU9bg.png",u="/assets/image-20260312090547665.DmVlvU2j.png",m="/assets/image-20260312090623769.BM1ijRTG.png",y=JSON.parse('{"title":"小龙虾的技能宝库：玩转 OpenClaw Skill","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/光安装小龙虾还不行，你得要会给它安装技能呀/光安装小龙虾还不行，你得要会给它安装技能呀.md","filePath":"AI人工智能/光安装小龙虾还不行，你得要会给它安装技能呀/光安装小龙虾还不行，你得要会给它安装技能呀.md","lastUpdated":1773312776000,"__rawMarkdown":"# 小龙虾的技能宝库：玩转 OpenClaw Skill\\n\\n## 前言\\n\\n\\n\\n**Skill** 是 **OpenClaw** 的扩展机制，类似于插件或应用，旨在为 OpenClaw 提供特定的功能能力。\\t通过 Skill，用户可轻松为 \\n\\nOpenClaw 添加新功能，而无需修改核心代码。\\n\\n\\n\\n## Skill 的分类\\n\\nOpenClaw 的 Skill 按来源和部署方式可分为三大类：内置 Skills、共享 Skills 和工作区 Skills。\\n\\n1. **内置 Skills**：随安装包一同发布（npm 包或 OpenClaw.app）。例如 `weather` 即为一个内置 Skill，用于实现实时天气查询。\\n\\n2. **托管/本地 Skills**：默认存放于 `~/.openclaw/skills` 目录。此类 Skill 为共享资源，可被任何工作区调用。\\n\\n3. **工作区 Skills**：默认存放于 `<workspace>/skills` 目录。`<workspace>` 指用户定义的工作区路径。例如，用户将某目录用于存放办公文件，该目录即可视为一个工作区。不同工作区间的 Skill 相互隔离，互不共享。\\n\\n实际使用中，用户可根据需求为 OpenClaw 配置相应体系的 Skill。\\n\\n\\n\\n## 使用 ClawHub 安装第三方 Skill\\n\\nClawHub 是 OpenClaw 官方提供的 Skill 管理与分发平台，用户可在此发现、安装及管理各类共享 Skill。\\n\\n### 访问 ClawHub\\n\\n打开浏览器，访问 ClawHub 官方网站：https://clawhub.ai\\n\\n![](assets/image-20260311231752219.png)\\n\\nClawHub 主页展示了热门及最新发布的 Skill，便于用户快速探索新功能。\\n\\n### 搜索 Skill\\n\\n点击顶部导航栏的 \\"Search\\" 链接进入搜索页面。\\n\\n![](assets/image-20260311233226605.png)\\n\\n在搜索框输入关键字（如 \\"wechat\\"、\\"github\\"、\\"file\\" 等）查找相关 Skill。搜索结果将展示 Skill 的基本信息，包括名称、图标、简介、作者、下载量及评分等。\\n\\n![](assets/image-20260311233258430.png)\\n\\n### 查看 Skill 详情\\n\\n点击感兴趣的 Skill 进入详情页。\\n\\n![image-20260311233441258](assets/image-20260311233441258.png)\\n\\n详情页包含以下信息：名称、简介、功能描述、使用场景、作者信息、版本历史、安装使用说明、用户评价、评分、依赖项及兼容性说明。建议用户详细阅读后，确认无误再进行安装。\\n\\n### 安装 ClawHub CLI\\n\\n下载 Skill 需使用 `clawhub` 命令行工具（CLI）。若尚未安装，请先在终端执行以下命令：\\n\\n```bash\\nnpm i -g clawhub\\n```\\n\\n![](assets/image-20260311234237483.png)\\n\\n安装完成后，可运行 `clawhub` 命令验证安装状态。若成功，将显示 ClawHub 版本号。\\n\\n![](assets/image-20260311234304859.png)\\n\\n### 使用 ClawHub 安装第三方 Skill\\n\\n默认情况下，`clawhub` 会将 Skill 下载至当前终端所在目录。通常我们希望将 Skill 下载至特定工作区，此时可指定存放目录。\\n\\n```bash\\nclawhub install xxxx --dir <您的工作区路径>\\n```\\n\\n示例如下：\\n\\n![](assets/image-20260312083431580.png)\\n\\n下载成功后，工作区目录下将出现新下载的 Skill（例如 `baidu-search`）。\\n\\n![](assets/image-20260312083530044.png)\\n\\n随后，请重启 OpenClaw 或向智能体发送指令 **“更新工作区 Skill”**。\\n\\n配置完成后，即可在对话中指定该 Skill 实现特定功能。例如：\\n\\n```text\\n使用 baidu-search Skill 搜索中国的节气信息\\n```\\n\\n由于 `baidu-search` 需要配置相应的 API Key，首次使用时会出现如下提示：\\n\\n![](assets/image-20260312084804933.png)\\n\\n此时需前往百度千帆平台创建专属 API Key。\\n\\n1. 注册并登录百度千帆平台：\\n\\n   ```text\\n   https://console.bce.baidu.com/qianfan/ais/console/apiKey\\n   ```\\n\\n2. 创建 API KEY。\\n\\n   ![](assets/image-20260312090150742.png)\\n\\n3. 设置 API KEY 权限。测试用途可选择全部权限。\\n\\n   ![](assets/image-20260312090455124.png)\\n\\n4. 复制生成的 Key，发送给智能体，指示其完成配置。\\n\\n   ![](assets/image-20260312090547665.png)\\n\\n   ***\\n\\n   ![](assets/image-20260312090623769.png)\\n\\n   如图所示，智能体已自动完成 Key 配置并执行了初始任务。\\n\\n\\n## 总结 [​](#总结)\\n\\n万少建立了一个专门讨论小龙虾OpenClaw的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n目前人已经超过200人了，私聊我进群。\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](https://blog.zbztb.cn/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),w={name:"AI人工智能/光安装小龙虾还不行，你得要会给它安装技能呀/光安装小龙虾还不行，你得要会给它安装技能呀.md"};function S(C,a,_,E,x,B){return s(),n("div",null,[...a[0]||(a[0]=[i("",48)])])}const F=l(w,[["render",S]]);export{y as __pageData,F as default};
